inline const SwitchInstruction& switch_instruction(bool bank_r,uint32_t pc) {
    if (pc<0x08020000u || pc>=0x08040000u || pc&1u) throw std::domain_error("mode-change PC outside fixed graph");
    const uint32_t slot=(pc-0x08020000u)/2u;
    const uint32_t index=bank_r?switch_index_r[slot]:switch_index_m[slot];
    if (!index) throw std::domain_error("mode-change PC outside recovered graph");
    return bank_r?switch_code_r[index-1]:switch_code_m[index-1];
}
